CREATE DATABASE IF NOT EXISTS `db_base` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `db_base`;

--
-- Creación de las cuentas para el servidor
--

CREATE USER IF NOT EXISTS 'manager'@'%' IDENTIFIED BY 'REPLACEME_BP';
GRANT SELECT,INSERT,UPDATE,DELETE ON db_base.* TO 'manager'@'%';
GRANT SELECT ON db_game.* TO 'manager'@'%';

CREATE USER IF NOT EXISTS 'reader'@'%' IDENTIFIED BY 'REPLACEME_GP';
GRANT SELECT ON db_game.* TO 'reader'@'%';

FLUSH PRIVILEGES;

--
-- Estructura para la tabla `cases`
--

CREATE TABLE `cases` (
  `id` int NOT NULL,
  `consulta` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `dif` int UNSIGNED NOT NULL,
  `isExam` tinyint(1) NOT NULL,
  `isSecondary` tinyint(1) NOT NULL,
  `isFinal` tinyint(1) NOT NULL,
  `data` json NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

--
-- Datos para la tabla `cases`
--

INSERT INTO `cases` (`id`,`consulta`,`dif`,`isExam`,`isSecondary`,`isFinal`,`data`) VALUES
(1,'SELECT nombre, apellidos FROM ciudadanos WHERE altura > 1.9 AND colorPelo = \"pelirrojo\"',1,0,0,0,'{\"id\":1,\"dif\":1,\"coste\":1,\"examen\":false,\"pistas\":[{\"titulo\":\"Color de pelo\",\"palabras\":[\"pelirrojo\"],\"descripcion\":\"Un testigo declara haber visto a un transportista <b>pelirrojo</b> parar la nave en un punto no autorizado durante el transporte.\"},{\"titulo\":\"Altura\",\"palabras\":[\"1.9\"],\"descripcion\":\"Además se ha fijado en que medía <b>más de 1,90</b> metros de altura.\"}],\"titulo\":\"Robo de Mercancía Peligrosa\",\"resumen\":\"Se ha detectado una pérdida de mercancía peligrosa durante su transporte y necesitan saber el <b>nombre</b> y <b>apellido</b> del responsable para poder arrestarlo.\",\"bounties\":[{\"efecto\":0,\"cantidad\":1,\"condicion\":0}],\"caducidad\":-1,\"secundario\":false}'),
(2,'SELECT idTitular FROM vehiculos WHERE marca=\"Llada\" AND color=\"negro\" AND idTitular IN(SELECT dni FROM ciudadanos WHERE apellidos=\"krakaro\")',1,0,0,0,'{\"id\":2,\"dif\":1,\"coste\":1,\"caducidad\":1,\"secundario\":false,\"examen\":false,\"titulo\":\"Twisted Sisters\",\"resumen\":\"Ha surgido un revuelo tras el asesinato de 3 miembros del grupo de traficantes Corgos formado por 4 hermanas. La última se encuentra en la cárcel pero quiere venganza y pide que encuentren al titular un coche sospechoso.\",\"pistas\":[{\"titulo\":\"Coche sospechoso\",\"descripcion\":\"Según la Corgo, la semana anterior a su arresto sintió que un coche la segía a todas partes, no se fijó en la matrícula, pero era un <b>coche negro de la marca Llada</b>, una marca conocida por ser la favorita de los Exukentes.\",\"palabras\":[\"negro\",\"Llada\"]},{\"titulo\":\"Un ajuste de cuentas\",\"descripcion\":\"Ella admite que podría ser un ajuste de cuentas, por eso mismo, sospecha que podría ser uno de los <b>Krakaro</b>.\",\"palabras\":[\"krakaro\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":3,\"efecto\":1,\"cantidad\":1},{\"condicion\":5,\"efecto\":1,\"cantidad\":1}]}'),
(3,'SELECT correo FROM pingBusquedas WHERE ip = \"148.48.91.102\" AND correo <> \"director@pickiecast.com\"',1,1,0,0,'{\"id\":3,\"dif\":1,\"coste\":1,\"caducidad\":1,\"secundario\":false,\"examen\":true,\"titulo\":\"Non Funkible Token\",\"resumen\":\"Han hackeado el servidor de la empresa de streaming PickleCast y han amenazado con publicar todos los datos <b>biométricos</b>, y todos los datos sensibles que tienen. Piden un rescate altísimo en cripto-monedas y han dado 24 horas para pagar. Se pide que se busque un correo del hacker, uno <b>distinto</b> al que ha usado, para ver si hay alguna forma de localizarlo.\",\"pistas\":[{\"titulo\":\"Phishing\",\"descripcion\":\"La compañía cree que el hacker ha empleado phising para obtener acceso, ya que el empleado Juanito Javanero acaba de indicar que ha perdido el acceso a su cuenta. La empresa no ha facilitado su correo: <b>juanitojavanero@picklecast.com</b>.\",\"palabras\":[\"juanitojavanero@picklecast.com\"]}],\"bounties\":[{\"condicion\":8,\"efecto\":0,\"cantidad\":1},{\"condicion\":0,\"efecto\":2,\"cantidad\":1},{\"condicion\":0,\"efecto\":4,\"cantidad\":10},{\"condicion\":1,\"efecto\":0,\"cantidad\":-3},{\"condicion\":1,\"efecto\":4,\"cantidad\":-5},{\"condicion\":2,\"efecto\":2,\"cantidad\":1}]}'),
(4,'SELECT dniPropietario FROM asistenteVoz WHERE log LIKE \"%bomba%\"',2,0,0,0,'{\"id\":4,\"dif\":2,\"coste\":1,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Smooth Criminal\",\"resumen\":\"Hay sospechas de que una serie de individuos están planeando un acto terrorista, y fuentes externas preveen que se usará algún tipo de explosivo.\",\"pistas\":[{\"titulo\":\"Palabras Clave\",\"descripcion\":\"Recomiendan buscar palabras clave como <b>bomba</b>,<b>explosivo</b>, o <b>carga</b>.\",\"palabras\":[\"bomba\",\"explosivo\",\"carga\"]}],\"bounties\":[{\"condicion\":8,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":4,\"cantidad\":5},{\"condicion\":0,\"efecto\":3,\"cantidad\":5}]}'),
(5,'SELECT dni FROM muricaGuns_armasRegistradas WHERE numSerie LIKE \"984%35\" AND marca = \"Luna\"',2,0,0,0,'{\"id\":5,\"dif\":2,\"coste\":2,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Yo no te pido la luna\",\"resumen\":\"Un joven feriseo afirma que han inculpado incorrectamente a su novia exukente llamada Karalina. Aunque admite que pertenece a una banda callejera, el joven asegura que ella nunca usariá un arma láser, y quiere que encontremos al auténtico culpable (con el dni debería de valer).\",\"pistas\":[{\"titulo\":\"Información del Arma\",\"descripcion\":\"Un agente ha conseguido acceder al arma mencionada, es de la marca <b>Luna</b>.\",\"palabras\":[\"Luna\"]},{\"titulo\":\"Información del Arma 2\",\"descripcion\":\"El número de serie está borrado, pero aún se pueden ver que empieza por <b>984</b> y termina con <b>35</b>.\",\"palabras\":[\"984\",\"35\"]}],\"bounties\":[{\"condicion\":8,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":1,\"cantidad\":2},{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":3,\"cantidad\":5},{\"condicion\":0,\"efecto\":4,\"cantidad\":-5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-5}]}'),
(6,'SELECT dni FROM vehiculos WHERE matricula LIKE \"%51%\" AND dni IN(SELECT dni FROM megaMilky_ventas WHERE idProducto BETWEEN 72 AND 74 ORDER BY cantidad DESC LIMIT 2)',2,1,0,0,'{\"id\":6,\"dif\":2,\"coste\":1,\"caducidad\":-1,\"secundario\":false,\"examen\":true,\"titulo\":\"Night of Fire\",\"resumen\":\"Unos conductores temerarios arrasan por la noche la sede de periodismo principal del EEL. Durante el acto terrorista pintan las paredes con mensajes de odio sobre cómo están discriminando a los Exukentes. También incendiaron el edificio y destrozaron el parque de delante haciendo donuts con los coches.\",\"pistas\":[{\"titulo\":\"Fuego Inusual\",\"descripcion\":\"El fuego tenía un color inusual, era <b>verde</b>. Un científico asegura que dicho color se ha producido por incendiar el sulfato de cobre junto con el alcohol. El sulfato de cobre se encuentra en <b>productos alguicidas</b>, añade.\",\"palabras\":[\"alguicida\"]},{\"titulo\":\"Donuts\",\"descripcion\":\"Gracias a los donuts, unas cámaras pudieron ver parte de una de las matrículas, por lo que se sabe que una contenía el número <b>51</b> en medio de la matrícula.\",\"palabras\":[\"51\"]}],\"bounties\":[{\"condicion\":8,\"efecto\":0,\"cantidad\":1},{\"condicion\":0,\"efecto\":2,\"cantidad\":1},{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":2,\"efecto\":2,\"cantidad\":1}]}'),
(7,'SELECT nombre, apellidos FROM ciudadanos WHERE nombre = \"hernesto\" AND apellidos = \"galeano\"',3,0,0,0,'{\"id\":7,\"dif\":3,\"coste\":1,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"La gata bajo la lluvia\",\"resumen\":\"Están ocurriendo una serie de asesinatos en un barrio, se rumorea que hay una banda de delincuentes causando estragos. La única información que se sabe del asunto es que en la noche de cada asesinato, se puede escuchar a un <b>gato maullando</b> cerca de la fuente del barrio, aunque nadie jamás ha llegado a ver tal gato.\",\"pistas\":[{\"titulo\":\"La grabadora bajo la fuente\",\"descripcion\":\"El agente ha encontrado un reproductor de audio oculto dentro de la fuente. Dentro habían 2 grabaciones, una contiene maullidos de gato, mientras que la otra contiene el siguiente poema recitado: Querida doña Varetta, del cielo sonaron las trompetas, y así como en Romeo y Julietta, por equivocación mi vida ya no tiene meta. Y tras quedar esta incompleta, ya sólo me queda esperar aquel fugaz cometa, el que descubra qué fuego hizo la silueta... de la más jóven de los Varetta. <b>Será de vital importancia obtener nombre y apellido de la persona que puso la grabadora en la fuente</b>\",\"palabras\":[\"varetta\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":1,\"cantidad\":1},{\"condicion\":6,\"efecto\":0,\"cantidad\":1},{\"condicion\":0,\"efecto\":3,\"cantidad\":10},{\"condicion\":0,\"efecto\":4,\"cantidad\":-5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-5}]}'),
(8,'SELECT zonaDestino FROM rutas WHERE zonaOrigen = \"wet groove\" AND fecha = \"2224-04-21\" GROUP BY zonaDestino ORDER BY COUNT(zonaDestino) desc LIMIT 1',3,0,0,0,'{\"id\":8,\"dif\":3,\"coste\":1,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Me colé en una fiesta\",\"resumen\":\"Pepuv quiere que encuentres el lugar al que más coches fueron después del incidente de la fiesta.\",\"pistas\":[{\"titulo\":\"Fecha del evento\",\"descripcion\":\"El humano dijo que la fiesta ocurrió el 21 de este mes.\",\"palabras\":[\"2224-04-21\"]},{\"titulo\":\"Nombre del local\",\"descripcion\":\"El local en el que se hizo la fiesta se llama <b>Wet Groove</b>.\",\"palabras\":[\"wet groove\"]},{\"titulo\":\"La puerta\",\"descripcion\":\"Tras llegar al establecimiento, los agentes descubrieron que la misteriosa puerta \",\"palabras\":[\"---\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":3,\"efecto\":1,\"cantidad\":2},{\"condicion\":0,\"efecto\":4,\"cantidad\":-15},{\"condicion\":0,\"efecto\":3,\"cantidad\":5}]}'),
(9,'SELECT numPuerto, entidadSolicitante, COUNT(fechaLlegada) AS veces FROM transbordos WHERE numpuerto BETWEEN 4 AND 8 GROUP BY numpuerto, entidadsolicitante HAVING veces >= 5',3,1,0,0,'{\"id\":9,\"dif\":3,\"coste\":0,\"caducidad\":-1,\"secundario\":false,\"examen\":true,\"titulo\":\"Deja Vu\",\"resumen\":\"Pepuv continuó investigando el caso anterior y ha encontrado algo sospechoso en los Transbordos de la bahía del EEL. Pide explícitamente una lista de la cantidad de transbordos hechos por cada empresa (entidadSolicitante) en cada puerto.\",\"pistas\":[{\"titulo\":\"Rango de puertos\",\"descripcion\":\"Según pepuv, las operaciones sospechosas ocurren del puerto 4 al 8.\",\"palabras\":[\"4\",\"8\"]},{\"titulo\":\"Cantidad extrema de Transbordos\",\"descripcion\":\"Sólo interesan aquellas empresas que superen los 5 transbordos en cada puerto.\",\"palabras\":[\"5\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":2,\"cantidad\":1},{\"condicion\":0,\"efecto\":1,\"cantidad\":10},{\"condicion\":8,\"efecto\":0,\"cantidad\":1},{\"condicion\":3,\"efecto\":0,\"cantidad\":1},{\"condicion\":5,\"efecto\":0,\"cantidad\":1}]}'),
(10,'SELECT * FROM corgomatic WHERE matricula IN(\"0274CJH\",\"0682ACY\",\"0285PRN\",\"0102MVM\",\"0427QEG\")',4,0,0,0,'{\"id\":10,\"dif\":4,\"coste\":0,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Just The Two of Us\",\"resumen\":\"Un supuesto detective independiente llamado Kevin solicita que colabores con él, pide que le muestres los cambios realizados en los vehículos de un puñado de sospechosos que está vigilando. Es necesario la matrícula, las fechas, y la descripción de los cambios.\",\"pistas\":[{\"titulo\":\"Lista de matrículas\",\"descripcion\":\"El papel que te ha dado Kevin contiene una lista de matrículas de vehículos.\",\"palabras\":[\"0274CJH\",\"0682ACY\",\"0285PRN\",\"0102MVM\",\"0427QEG\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":0,\"efecto\":1,\"cantidad\":1},{\"condicion\":3,\"efecto\":0,\"cantidad\":1},{\"condicion\":1,\"efecto\":0,\"cantidad\":-1}]}'),
(11,'SELECT nombre, apellidos FROM ciudadanos WHERE dni IN(SELECT dniEmpleado FROM transbordos_empleados WHERE idTransbordo IN (SELECT id FROM transbordos WHERE fechaLlegada BETWEEN \"2224-03-18\" AND \"2224-04-24\"))',4,0,0,0,'{\"id\":11,\"dif\":4,\"coste\":0,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Gangsta Paradise\",\"resumen\":\"Kevin ha descubierto una red de tráfico ilegal, pero hay algo que se le escapa de las manos, te pide que le devuelvas una lista con nombre y apellidos de cada funcionario que haya realizado una recogida de mercancía en la bahía de transbordos\",\"pistas\":[{\"titulo\":\"Intervalo\",\"descripcion\":\"Kevin dijo que Pepuv le mostró un rastro de sucesos que ocurrieron en la zona de transbordos entre el 2224-03-18 y el 2224-04-24.\",\"palabras\":[\"2224-03-18\",\"2224-04-24\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":1,\"cantidad\":2},{\"condicion\":1,\"efecto\":1,\"cantidad\":1}]}'),
(12,'SELECT dni FROM ciudadanos WHERE raza = \"exukente\" AND dni IN (SELECT dniCliente FROM rinconDelTurro_mesas WHERE idReserva = IN(SELECT idReserva FROM rinconDelTurro_reservas Where hora = \"2224-04-27 22:00\"))',4,1,0,0,'{\"id\":12,\"dif\":4,\"coste\":2,\"caducidad\":-1,\"secundario\":false,\"examen\":true,\"titulo\":\"Limón y Sal\",\"resumen\":\"Kevin ha colocado un micro oculto en el restaurante Rincón del Turro para espiar a la gente y confirmar si hablan de algo sospechoso. Quiere que descubras el dni de aquellos que tienen acceso a la zona secreta del restaurante.\",\"pistas\":[{\"titulo\":\"Establecimiento\",\"descripcion\":\"El restaurante se llama <b>Rincón del Turro</b>\",\"palabras\":[\"---\"]},{\"titulo\":\"Grabaciones\",\"descripcion\":\"Dado que Kevin no puede volver al restaurante, tus agentes han ido en su lugar para recuperar la grabadora oculta, han transcrito su contenido a texto y lo han metido en la nueva tabla <b>GrabacionesRestaurante</b>.\",\"palabras\":[\"---\"]},{\"titulo\":\"Contraseña\",\"descripcion\":\"Kevin mencionó que una forma de acceder era usando la contraseña que había encontrado, pero con eso no bastaba.\",\"palabras\":[\"Limón y Sal\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":2,\"cantidad\":1},{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":5,\"efecto\":0,\"cantidad\":1},{\"condicion\":6,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":4,\"cantidad\":15},{\"condicion\":0,\"efecto\":3,\"cantidad\":5},{\"condicion\":1,\"efecto\":4,\"cantidad\":-5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-5}]}'),
(13,'SELECT R1.matricula, R2.zonaDestino FROM rutas as R1 INNER JOIN rutas AS R2 ON R1.zonaDestino = R2.zonaOrigen WHERE R1.matricula = R2.matricula AND R1.fecha = R2.fecha AND R1.zonaOrigen = \"Calle Korumiv\" AND R1.zonaDestino = \"Rincon del Turro\"',5,0,0,0,'{\"id\":13,\"dif\":5,\"coste\":0,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"The step bellow hell\",\"resumen\":\"Kevin te pregunta si le puedes hacer una lista de los vehículo que vayan desde la Calle Korumiv y que hagan una parada por el Rincón del Turro. Concretamente quiere saber las matrículas y el lugar de destino al que van tras parar en dicho establecimiento.\",\"pistas\":[{\"titulo\":\"Parada intermedia\",\"descripcion\":\"El <b>Rincón del Turro</b>, supuestamente un punto intermedio de recogida para el tráfico del mercado negro.\",\"palabras\":[\"Rincón del Turro\"]},{\"titulo\":\"Salida de los sospechosos\",\"descripcion\":\"La <b>Calle Korumiv</b> del distrito exukente suele tener poca vigilancia por estar mayormente en desuso. No para el mercado negro aparentemente.\",\"palabras\":[\"Calle Korumiv\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":1,\"efecto\":0,\"cantidad\":-1},{\"condicion\":0,\"efecto\":3,\"cantidad\":5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-5},{\"condicion\":3,\"efecto\":0,\"cantidad\":1}]}'),
(14,'SELECT nombre, apellido FROM ciudadanos WHERE dni = ( SELECT titular FROM viviendas AS V INNER JOIN ciudadanos as C ON V.titular = C.dni WHERE direccion LIKE \"%Kroxik Takep 31th%\" AND titular IN( SELECT propietario FROM vehiculos WHERE matricula IN( SELECT C.matricula FROM corgomatic AS C INNER JOIN rutas AS R ON C.matricula = R.matricula WHERE C.fecha = R.fecha AND C.fecha = \"2224-04-28\" AND zonaOrigen = \"Corgomatic\" ) ) )',5,0,0,0,'{\"id\":14,\"dif\":5,\"coste\":0,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Scourge of the Universe\",\"resumen\":\"Gracias a ti, Kevin ha podido observar más cerca que nunca los movimientos de la sospechosa mafia \\"La Colmena\\". Además de la posible localización de una persona importante en la mafia, se sospecha que están aliados paradógicamente con un humano. Los datos que ha conseguido no son muy conexos pero quizás tú puedes darle un sentido y sacar un nombre en claro, nombre y apellidos para ser más precisos.\",\"pistas\":[{\"titulo\":\"Fecha de la persecución\",\"descripcion\":\"Kevin siguió el coche sospechoso el 2224-04-28.\",\"palabras\":[\"2224-04-28\"]},{\"titulo\":\"Modificación del vehículo\",\"descripcion\":\"El coche entró en el taller mecánico de coches \\"Corgomatic\\"\",\"palabras\":[\"---\"]},{\"titulo\":\"Punto de encuentro sospechoso\",\"descripcion\":\"¿Por qué un humano iría a aliarse con una mafia exukente? En cualquier caso, sabemos que será en el callejón <b>Kroxik Takep 31th</b>\",\"palabras\":[\"Kroxik Takep 31th\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":1,\"efecto\":0,\"cantidad\":-2},{\"condicion\":0,\"efecto\":3,\"cantidad\":5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-5},{\"condicion\":3,\"efecto\":0,\"cantidad\":1}]}'),
(15,'SELECT V.dni FROM vehiculos AS V INNER JOIN rutas AS R on V.matricula=R.matricula WHERE V.marca=\"Hamburghini\" AND V.color=\"%amarillo%\" AND R.zonaDestino=\"Callejón Gavku\"',5,0,0,1,'{\"id\":15,\"dif\":5,\"coste\":0,\"caducidad\":-1,\"secundario\":false,\"examen\":false,\"titulo\":\"Hijo de la Luna\",\"resumen\":\"El jefe de La Colmena está muerto, se nos adelantó el gobierno, pero Kripo está nervioso, y se le ha caído un papel con datos que sugieren que aún hay cabos sueltos. El dni del que está detrás de todo esto es la solución.\",\"pistas\":[{\"titulo\":\"Noticias (Zona de huída)\",\"descripcion\":\"El jefe de La Colmena huyó hacia la bahía de transbordos más cercana a su casa.\",\"palabras\":[\"Avenida Kosmi\"]},{\"titulo\":\"Noticias (fecha)\",\"descripcion\":\"La noticia es del hoy\",\"palabras\":[\"2224-04-29\"]},{\"titulo\":\"Noticias (Muerte)\",\"descripcion\":\"Un funcionario lo reconoció y llamó a la policía. El fujititvo reaccionó de forma agresiva y la policía tuvo que disparar.\",\"palabras\":[\"---\"]},{\"titulo\":\"Noticias (Vehículo)\",\"descripcion\":\"El vehículo en el que huyó fue confiscado para el futuro análisis\",\"palabras\":[\"---\"]},{\"titulo\":\"Kripo (Correo)\",\"descripcion\":\"El papel que se le cayó a Kripo tenía el supuesto correo del jefe de La Colmena.\",\"palabras\":[\"vikalkontrov@antmsg.exu\"]},{\"titulo\":\"Kripo (Almacén Secreto)\",\"descripcion\":\"En el papel de Kripo habían unidos por una línea las palabras Almacén Secreto y Parásito de la Ascensión.\",\"palabras\":[\"Parásito de la Ascensión\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":99},{\"condicion\":8,\"efecto\":1,\"cantidad\":-999}]}'),
(100,'SELECT numPuerto FROM transbordos WHERE fechaLlegada = \"2224-04-18\" AND entidadSolicitante = \"Nidolé\"',1,0,1,0,'{\"id\":100,\"dif\":1,\"coste\":0,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"It’s my party (and i cry if i want to)\",\"resumen\":\"Un niño feriseo se ha colado en la oficina llorando? Debería indicarle a la policía el número de puerto en el que se harán las operaciones.\",\"pistas\":[{\"titulo\":\"Mañana\",\"descripcion\":\"Lo que esea que querían hacer con su padre va a ocurrir mañana en la bahía de transbordos\",\"palabras\":[\"2224-04-18\"]},{\"titulo\":\"La nave objetivo\",\"descripcion\":\"La nave que desembarca pertenece a Nidolé, una famosa megacorporación humana de alimentos procesados\",\"palabras\":[\"Nidolé\"]}],\"bounties\":[{\"condicion\":8,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":0,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":3,\"cantidad\":5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-15},{\"condicion\":0,\"efecto\":4,\"cantidad\":-10},{\"condicion\":1,\"efecto\":4,\"cantidad\":10}]}'),
(101,'SELECT matricula, fecha FROM rutas WHERE distanciaViaje > 50.0 AND zonaOrigen = \"Avenida Reina Forilisia\" OR zonaOrigen = \"Plaza Ojo de Chlungus\" OR zonaOrigen = \"Calle Giripimbas 3º\"',1,0,1,0,'{\"id\":101,\"dif\":1,\"coste\":0,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"Life is a Highway\",\"resumen\":\"Una empresa nueva de servicios ha solicitado una lista con la matrícula y la fecha de los viajes que hayan tomado más de 50 kilómetros en recorrerse.\",\"pistas\":[{\"titulo\":\"Desplazamiento largo\",\"descripcion\":\"50 kilómetros es un viaje bastante largo. Prácticamente abarca toda la longitud de la EEL.\",\"palabras\":[\"50\"]},{\"titulo\":\"Calles residenciales\",\"descripcion\":\"La empresa ha indicado 3 calles residenciales como origen de los desplazamientos. Estas calles son \\"<b>Avenida Reina Forilisia</b>\\", \\"<b>Plaza Ojo de Chlungus</b>\\" y \\"<b>Calle Giripimbas 3º</b>\\". Todas pertenecen a la parte de la \\"cola\\" (trasera) del EEL.\",\"palabras\":[\"Avenida Reina Forilisia\",\"Plaza Ojo de Chlungus\",\"Calle Giripimbas 3º\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":2,\"cantidad\":1},{\"condicion\":0,\"efecto\":1,\"cantidad\":3},{\"condicion\":0,\"efecto\":4,\"cantidad\":10},{\"condicion\":1,\"efecto\":4,\"cantidad\":-5}]}'),
(102,'SELECT idTitular FROM vehiculos WHERE matricula = \"0312XIO\"',2,0,1,0,'{\"id\":102,\"dif\":2,\"coste\":2,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"Greased Lightning\",\"resumen\":\"Han anunciado el robo de unas decoraciones en un bar, los artefactos robados se consideran parte de la cultura Ferisea y estaban protegidos por el gobierno. El valor que tienen es histórico por lo que es considerado un acto puramente de vandalismo. Se busca el <b>dni</b> de algún culpable.\",\"pistas\":[{\"titulo\":\"Fecha del vandalismo\",\"descripcion\":\"Ocurrió el día <b>2224-04-16</b>.\",\"palabras\":[\"2224-04-16\"]},{\"titulo\":\"El vehículo de huída\",\"descripcion\":\"Nadie ha visto quién o quienes han sido, pero los agentes han encontrado algunos testigos que comentaron que el vehículo de huida usado tenía <b>pintura verde oscura metalizada</b> y tendría que medie menos de <b>3,5 metros de largo</b>.\",\"palabras\":[\"verde oscura metalizada\",\"3.5\"]},{\"titulo\":\"Vehículo dañado\",\"descripcion\":\"La policía llegó tarde aquella noche, pero consiguieron disparar a las <b>ruedas traseras y la luna trasera antes de que consiguiesen escapar</b>.\",\"palabras\":[\"ruedas traseras\",\"luna trasera\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":3,\"cantidad\":10},{\"condicion\":0,\"efecto\":4,\"cantidad\":5},{\"condicion\":3,\"efecto\":0,\"cantidad\":2},{\"condicion\":6,\"efecto\":0,\"cantidad\":1}]}'),
(103,'SELECT dniCliente FROM megaMilky_ventas WHERE idProducto = 97 AND fecha BETWEEN \"2224-03-28\" AND \"2224-04-17\"',2,0,1,0,'{\"id\":103,\"dif\":2,\"coste\":1,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"Pest of the Cosmos\",\"resumen\":\"Unos vándalos dibujaron un grafiti despectivo en un edificio de una empresa de Exukentes, bajo el grafiti se puede leer que han escrito \\"La peste del cosmos\\". Sería de utilidad para la policía tener una lista con los dni de candidatos a sospechosos.\",\"pistas\":[{\"titulo\":\"Fecha del vandalismo\",\"descripcion\":\"Se sabe que el grafiti se hizo la noche del <b>2224-04-17</b>.\",\"palabras\":[\"2224-04-17\"]},{\"titulo\":\"Papeleras cercanas\",\"descripcion\":\"Nuestros agentes encontraron en papeleras cercanas a lo ocurrido, <b><i>muchas</i></b> latas de grafiti vacías de la marca \\"<b>Dooburu</b>\\", además, las latas encontradas contienen fechas de fabricación del <b>2224-03-28</b>.\",\"palabras\":[\"Dooburu\",\"2224-03-28\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":4,\"cantidad\":5},{\"condicion\":3,\"efecto\":2,\"cantidad\":1},{\"condicion\":5,\"efecto\":2,\"cantidad\":1}]}'),
(104,'SELECT direccion FROM viviendas WHERE direccion LIKE \"Calle%9º\" and direccion NOT LIKE \"%Korumiv%\"',2,0,1,0,'{\"id\":104,\"dif\":2,\"coste\":0,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"I just called to say i love you\",\"resumen\":\"Una mujer Ferisea ha aparecido en la puerta del despacho junto con sus 5 hijos (?!). Ha venido corriendo a las oficinas porque recibió una llamada sospechosa del marido después de no saber nada de él en varios días y la policía no parece tener especial interés en ayudarla.\",\"pistas\":[{\"titulo\":\"La última compra\",\"descripcion\":\"La última vez que vió al marido fue el día <b>2224-04-14</b>, le dijo que iba al <b>supermercado</b> pero no volvió\",\"palabras\":[\"2224-04-14\"]},{\"titulo\":\"Datos del marido\",\"descripcion\":\"\\"Es muy bueno, y llevan 20 años casados\\". Es ingeniero. No tiene amigos Corgos. Su dni es el <b>618</b>.\",\"palabras\":[\"618\"]},{\"titulo\":\"La llamada\",\"descripcion\":\"En la llamada su marido le dice que está de viaje con unos amigos corgos a pesar de no haber avisado antes...\",\"palabras\":[]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":2,\"cantidad\":1},{\"condicion\":2,\"efecto\":0,\"cantidad\":1},{\"condicion\":4,\"efecto\":0,\"cantidad\":1},{\"condicion\":5,\"efecto\":0,\"cantidad\":1},{\"condicion\":6,\"efecto\":0,\"cantidad\":1},{\"condicion\":7,\"efecto\":3,\"cantidad\":20}]}'),
