(106,'',3,0,1,0,'{}'),
(107,'SELECT proveedor FROM paulsPizzeria_inventario WHERE tipo = \"animatrónico\" GROUP BY tipo',4,0,1,0,'{\"id\":107,\"dif\":4,\"coste\":1,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"Join Us for a Bite\",\"resumen\":\"Ha surgido el rumor de que han estado desapareciendo niños en una pizzería familiar llamada “Paul’s Pizzeria”. El guardia de seguridad es el único testimonio que puede aclarar las cosas sobre el rumor.\",\"pistas\":[{\"titulo\":\"El fundador\",\"descripcion\":\"Se conoce que a parte de él y otros guardias anteriores, la única persona que ha trabajado allí es el fundador del establecimiento <b>Mailliw Afton</b>, pero se supone que debería estar muerto.\",\"palabras\":[\"Mailliw Afton\"]},{\"titulo\":\"El testimonio\",\"descripcion\":\"Se interrogó al guardia de seguridad, el cual parece estar incómo hablando sobre el tema, pero menciona que le ha resultado extraño que a veces haya visto un animatrónico diferente al resto. A falta de una lista de los animatrónicos originales habrá que preguntar a las empresas que los fabricaron…\",\"palabras\":[]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":2},{\"condicion\":0,\"efecto\":1,\"cantidad\":1},{\"condicion\":0,\"efecto\":3,\"cantidad\":5},{\"condicion\":1,\"efecto\":3,\"cantidad\":-5},{\"condicion\":7,\"efecto\":0,\"cantidad\":1}]}'),
(108,'SELECT objeto FROM paulsPizzeria_inventario WHERE proveedor = \"Corgomatic\" AND objeto NOT IN(\"Hernesto el Hamster\", \"Lucas el Lobo\", \"Gloria la Gallina\", \"Paul el oso Polar\")',4,0,1,0,'{\"id\":108,\"dif\":4,\"coste\":0,\"caducidad\":-1,\"secundario\":true,\"examen\":false,\"titulo\":\"Die in a Fire\",\"resumen\":\"El dueño de Corgomatic se ha presentado en tu oficina para hablarte sobre la relación que tenía con Mailliw Afton. Todas las señales apuntan a una sola cosa. Hay que encontrar el quinto animatrónico en el  inventario del establecimiento.\",\"pistas\":[{\"titulo\":\"Lista de animatrónicos originales\",\"descripcion\":\"Si hay un quinto animatrónico debería aquel que no tenga el nombre de los originales (Hernesto el Hamster, Lucas el Lobo, Gloria la Gallina y Paul el oso Polar).\",\"palabras\":[\"Hernesto el Hamster\",\"Lucas el Lobo\",\"Gloria la Gallina\",\"Paul el oso Polar\"]}],\"bounties\":[{\"condicion\":0,\"efecto\":0,\"cantidad\":1},{\"condicion\":8,\"efecto\":1,\"cantidad\":-99},{\"condicion\":3,\"efecto\":0,\"cantidad\":1}]}');

