(32,"{·id·:32,·titulo·:·Casos2d4·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·CASO_COMPLETADO=107·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·IncluirCaso - 108·,·EmpezarDialogo - JEFE·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Oyes los pasos de un corgo acercándose a tu oficina.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Buenos días, Kripo me ha dicho que tú eres el que está metido en el caso de Pauls Pizzeria.·,·Efectos·:·Oscurecer=(true), Cambio Perfil=(Corgo neutro)·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Permiteme prensentarme.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Yo soy el dueño de Corgomatic, vengo a hablarte sobre mi relación de trabajo con Mailliw Afton.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Se apoya en la pared, mirando a la esquina superior derecha.·,·Efectos·:·Oscurecer=(false), Cambio Perfil=()·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:·Oscurecer=(true), Cambio Perfil=(Corgo neutro)·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Fue un gran genio. Hace años colaboramos juntos para crear los animatrónicos que hoy en día siguien funcionando.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Él se encargó de los diseños, y yo de construirlos.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Me fascinó el sistema de cierre de resortes que inventó para poder aguantar toda la electrónica dentro de los animatrónicos.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Uno de esos genios de los que sólo hay uno cada 100 años...·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Me entristece que haya algún depravado raptando niños allí, pero no puede ser Mailliw Afton, murió hace años.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Aunque es cierto que <b>desapareció</b> y nunca encontraron su cuerpo.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Además, me sorprende que nunca hayan llevado los animatrónicos de vuelta aquí para hacerles revisión y reparar lo que haga falta.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Hace poco llevé a mi familia allí, y parecían estar como nuevo.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Que las cosas que construyo las hago para que duren, obviamente.·,·Efectos·:·Cambio Perfil=(Corgo contento)·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Pero es imposible que unos robots en constante funcionamiento no se hayan averiado ni una sola vez en los 40 años que llevan funcionando…·,·Efectos·:·Cambio Perfil=(Corgo neutro), Dar Opciones=(El guardia dijo que... @ guardia)·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·¿Cómo? ¿El guardia dice que vió a un animatrónico inusual? Los animatrónicos que construí no son los únicos presentes hoy en día, pero los míticos 4 del escenario los construí yo.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:·guardia·},{·Dialogo·:·<b>Hernesto el Hamster, Lucas el Lobo, Gloria la Gallina, y Paul el oso Polar</b>. No recuerdo haber construido un <b>quinto</b>.·,·Efectos·:·Cambio Perfil=(Corgo sus)·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·No creo que pueda ayudarte mucho más. Me iré.·,·Efectos·:·Cambio Perfil=(Corgo neutro)·,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·De todas formas ha sido un placer,·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·me han dicho que los datos que comparto al CSE te han servido de ayuda en tus casos.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··},{·Dialogo·:·Que tenga usted un buen día.<size=40%>Eso dicen los humanos, creo.·,·Efectos·:··,·Grupo·:·JEFE·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}"),
(33,"{·id·:33,·titulo·:·PostCasos2d4·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·CASO_COMPLETADO=108·,·probabilidad·:60,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - AFTON·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Te ha llegado una notificación al móvil.·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·AFTON·,·Etiqueta·:··},{·Dialogo·:·Es la última noticia en el periódico/blog de Pepuv:·,·Efectos·:··,·Grupo·:·AFTON·,·Etiqueta·:··},{·Dialogo·:·'Tras una década después de su muerte, se encuentra el cadáver de Mailliw Afton dentro de uno de los animatrónicos,'·,·Efectos·:··,·Grupo·:·AFTON·,·Etiqueta·:··},{·Dialogo·:·'Ayer, la policía acordonó el establemcimiento inmediatamente.'·,·Efectos·:··,·Grupo·:·AFTON·,·Etiqueta·:··},{·Dialogo·:·'Hoy el establecimiento entró en combustión, y tras apagar el fuego, el animatrónico que guardaba el cuerpo del señor Afton desapareció.'·,·Efectos·:··,·Grupo·:·AFTON·,·Etiqueta·:··},{·Dialogo·:·(Unas palabras resuenan en tu cabeza tras leer el artículo… <#FF2020><b>I ALWAYS COME BACK</b></color>)·,·Efectos·:··,·Grupo·:·AFTON·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}"),
(34,"{·id·:34,·titulo·:·InicioDif5·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·CASO_INTENTADO=12·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - JOIN·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Una última vez, vuelve a sonar Worbulo llamando a la puerta de la misma forma delicada de siempre.·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·Buenos días <val[nick]>, vengo a lo de siempre.·,·Efectos·:·Oscurecer=(true),Cambio perfil=(Corgo neutro)·,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·Nada nuevo por parte de la base de datos, pero ahora deberías ser capaz de usar las cláusulas <b>JOIN</b>.·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·Con estas podrás combinar dos o más tablas que tengan una columna relacionada.·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·Probablemente la mayoría de los casos anteriores se podrían haber solucionado más rápido con esto.·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·Lo que tiene la tecnología ¿Eh?·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·Pues eso, nada más por hoy.·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··},{·Dialogo·:·¡<i>Corulm</i>!·,·Efectos·:··,·Grupo·:·JOIN·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}"),
(35,"{·id·:35,·titulo·:·Casop1d5·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·CASO_INTENTADO=12·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - COLMENA·,·IncluirCaso - 13·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·¡Hoooola voz narradora de <val[nick]>!·,·Efectos·:·Oscurecer=(true), Cambio Perfil=(Epitaf contenta)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·¿Qué estás diciendo Epitaf? <val[nick]> no tiene ninguna voz narradora... A veces no sé lo que pasa por tu cabeza.·,·Efectos·:·Cambio Perfil=(Kevin neutro2)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·En <b><i>sú</b></i> cabeza dirás.·,·Efectos·:·Cambio Perfil=(Epitaf suegra)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·... El caso <val[nick]>, es que he obtenido nuevos datos sobre las mafias.·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Una de ellas se hacen llamar <#FFFF20><b><i>La Colmena<i></i></i></b></color>. Parece estar formada exclusivamente por exukentes.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Pero más importante que eso, he descubierto que el mercado negro está mucho más extendido de lo que creía.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Tengo unas pistas que me pueden ayudar a ver mejor los movimientos en el mercado negro, pero como siempre, me faltan datos.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·¿Podrías hacer una lista de los vehículo que vayan desde la “<i>Calle Korumiv</i>” y que hagan una parada por el <i>Rincón del Turro</i>? Concretamente quiere saber las matrículas y el lugar de destino al que van tras parar en dicho establecimiento.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Concretamente me gustaría saber las matrículas y el lugar de destino al que van tras parar en dicho establecimiento.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Por favor <val[nick]>, esto puede ser clave para el futuro de toda la Estación Espacial Láctea.·,·Efectos·:·Cambio Perfil=(Kevin neutro2)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Estaré atento a tu respuesta.·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Quiere decir que yo estaré detrás del teléfono...·,·Efectos·:·Cambio Perfil=(Epitaf decepcionada)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Hasta luego voz narradora ~·,·Efectos·:·Cambio Perfil=(Epitaf contenta)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:·Oscurecer=(false), Cambio Perfil=()·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·(¿Se ha ido ya?)·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·(Fiu...)·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}"),
(36,"{·id·:36,·titulo·:·Casop2d5·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·CASO_COMPLETADO=13·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - COLMENA·,·IncluirCaso - 14·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·(Se escuchan los pasos de...)·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·(AAAAAAH, SU AURA)·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·¿Qué? Luego me lo sigues contando Epitaf.·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Buenos días <val[nick]>. Estuve espiando a los individuos de la lista que te pedí.·,·Efectos·:·Cambio Perfil=(Kevin contento)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·¡Y tengo buenas noticias...!·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Y otras no tan buenas.·,·Efectos·:·Cambio Perfil=(Kevin neutro2)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·La buena es que el <i>28 de este mes</i> me puse a seguir el coche de uno de los sospechosos hasta corgomatic donde le hicierona algún cambio.·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Lo curioso es que el coche del sospechoso no era el mismo, están esforzándose mucho para obfuscar sus rastros.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·No pude apuntar la matricula porque la ocultaron, y por desgracia lo perdí de vista por culpa de un camión conducido por IA.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Qué conveniente para ellos...·,·Efectos·:·Cambio Perfil=(Kevin neutro2)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Esto último no es la mala noticia.·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·La mala noticia es que he podido interceptar una llamada de un miembro de <#ffff20>La Colmena</color>. Estába dándole órdenes un humano.·,·Efectos·:·Cambio Perfil=(Kevin sus)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Esto no me gusta nada. Sabemos que <#ffff20>La Colmena</color> es una banda exclusiva de exukentes. ¿Qué pinta un humano aliándose con ellos y dando órdenes?·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·La única información útil que pude sacar fue parte de la dirección de una vivienda, los filtros de ruido no han conseguido limpiar el audio para sacar la dirección completa,·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·pero al menos se sabe algo de una reunión futura en el callejón <b><i>Kroxik Takep 31th</i></b>.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Si puedes descartar datos con tu aparato y darme algún nombre sería clave.·,·Efectos·:·Cambio Perfil=(Kevin neutro2)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Siento que estamos peligrosamente cerca de descubrir algo que puede cambiar el curso de la Estación Espacial Láctea.·,·Efectos·:·Cambio Perfil=(Kevin contento)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Puedo olerte narrador...·,·Efectos·:·Cambio Perfil=(Epitaf stare)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·¿Qué?·,·Efectos·:·Cambio Perfil=(Kevin neutro2)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Creo que mi teoría de que la oficina está encantada de lo sucia que está va tomando forma.·,·Efectos·:·Cambio Perfil=(Epitaf suegra)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Quizás el narrador es un espíritu atormentado por el horroroso estilo de la oficina.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·(NO SOY UN ESPÍRITU)·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·>:D·,·Efectos·:·Cambio Perfil=(Epitaf contenta)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·En fin...·,·Efectos·:·Cambio Perfil=(Kevin neutro)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Tú haz tu trabajo como siempre has hecho. Si conseguimos descubrir el nombre del jefe que controla todo en <#ffff20>La Colmena</color>, todo se solucionará.·,·Efectos·:·Cambio Perfil=(Kevin contento)·,·Grupo·:·COLMENA·,·Etiqueta·:··},{·Dialogo·:·Hasta la próxima, <val[nick]>.·,·Efectos·:··,·Grupo·:·COLMENA·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}"),
(37,"{·id·:37,·titulo·:·CasopEd5·,·diario·:false,·momentoComprobable·:0,·condicionUnparsed·:·CASO_COMPLETADO=14·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·EmpezarDialogo - KRIPO·,·IncluirCaso - 15·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Te llega una noticia al móvil, pero te resulta extraño.·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·No viene ni del periódico de Pepuv, ni de la antigua sede aún en reconstrucción.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Viene del Organismo Gubernamental de la Estación Espacial Láctea (?)·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'Esta mañana se descubrió huyendo al jefe exukente de una organización terrorista en la EEL formada por exukentes.'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'La policía pudo reaccionar a tiempo y parale las patas en la bahía de transbordos de la Avenida Kosmi.'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'Tras la reacción agresiva del jefe, los policías no tuvieron otra opción que disparar.'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'El coche en el que huyó ha sido confiscado para su posterior análisis.'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'Esto significa el fin del terror, la seguridad de los niños, y de los trabajadores que tanto se esfuerzan.'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'Pero la cosa no va a quedar aquí, dijo un ministro. Estamos dispuestos a seguir protegiendo nuestro hogar cueste lo que cueste.'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·La noticia sigue con algo más de relleno.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Mientras terminas de leer la noticia, aparece Kripo...·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Hola <val[nick]>... Sólo venía a darte el papeleo usual del CSE... ·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Kripo pausa y cruza su mirada con tu móvil el cuál tenía el título de la noticia que acabas de leer.·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·...¿Cómo? Oh no...·,·Efectos·:·Cambio Perfil=(Kripo neutro), Dar Opciones=(¿Ocurre algo Kripo? @ ohno)·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·¡No puedo seguir hablándote, tengo prisa!·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:·ohno·},{·Dialogo·:·No se ha despedido, no ha cerrado la puerta y se ha ido corriendo.·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Pero al correr, algunos papeles que llevaba en el montón de folios se caen.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·La mayoría informes internos, pero hay uno extraño.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Es un diagrama con muchos carácteres Exukentes escritos y unidos entre ellos.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·El traductor universal consigue traducir los siguientes términos:·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'Correo Jefe Colmena --- vikalkontrov@antmsg.exu'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·'Almacén secreto --- Arma --- Parásito de la Ascensión --- Leyenda realeza exukente'·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Muchos terminos están rodeados varias veces...·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Sea lo que sea, quizás valga la pena investigarlo...·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··},{·Dialogo·:·Todo por Kripo.·,·Efectos·:··,·Grupo·:·KRIPO·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:·CM+99, CD+99·}"),
(38,"{·id·:38,·titulo·:·GoodEnding·,·diario·:true,·momentoComprobable·:2,·condicionUnparsed·:·CASO_COMPLETADO=15·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·SetDialogueEvent - ENDING = 1·,·EmpezarDialogo - ENDING·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Un momento... esta persona es...·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¿Un ministro humano?·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Más rápido que tus pensamientos es Kripo, que aparece corriendo por la puerta.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¡<val[nick]>!·,·Efectos·:·Cambio Perfil=(Kripo contento)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¡Has sido tú!·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¡No me lo puedo creer!·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Imagino que serás consciente ya, pero lo que has hecho ha ayudado a todo el pueblo exukente...·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Verás, sabía que alguien del gobierno nos quería fuera de aquí y...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¡Ah! Mi papel... Ya veo...·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Leíste los datos que estuve recabando en secreto, hehe...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Supongo que tengo mucho que explicar...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Verás, mi nombre completo es Kripo Kosmi, en realidad soy el príncipe exukente.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Sí... muchos no lo saben pero estas marcas azules en mi cabeza son símbolo de mi... '<#2020ff><i><#7070ff>sangre azul</color></i></color>'.·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·La mayoría de exukentes también tienen marcas azules, pero se las pintan ellos por encima. Cosas de nuestra cultura.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·La cosa es que trabajé en secreto aquí en el CSE para descubrir por mi cuenta quién quería echar a toda mi especie del EEL.·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Parece que ha sido cosa del destino que se me callese el papel...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Kripo se tumba...·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Yo, Kripo Kosmi, en nombre mi familia real y de toda mi querida gente, te doy las gracias.·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·La paz que buscábamos cuando firmamos el tratado fue honesta. Y gracias a ti podremos convivir juntos, por fin.·,·Efectos·:·Cambio Perfil=(Kripo contento)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Espero que aceptes este abrazo como símbolo de alianza.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Los exukentes no lo expresamos de esta forma, pero siendo tú un humano...·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Creo que demuestro respeto al imitar tus costumbres.·,·Efectos·:·Cambio Perfil=(Kripo neutro), Dar Opciones=(Abrazarle @ abrazo)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·ENDING·,·Etiqueta·:·abrazo·},{·Dialogo·:·Te resulta extraño abrazar a un exukente.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Su exoesqueleto hace que sientas que estás abrazando un cangrejo muy grande.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Pero igualmente, sientes su agradecimiento.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Y así decidiste terminar esta aventura.·,·Efectos·:·Oscurecer=(false)·,·Grupo·:·ENDING·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}"),
(39,"{·id·:39,·titulo·:·BadEnding·,·diario·:true,·momentoComprobable·:2,·condicionUnparsed·:·OR(CASO_PERDIDO=15,CASO_PERDIDO=14,CASO_PERDIDO=13)·,·probabilidad·:100,·cinematicFile·:{·cinematica·:[{·instrucciones·:[·SetDialogueEvent - ENDING = 2·,·EmpezarDialogo - ENDING·,·SetDialogueEvent - game_over = 1·],·separador·:·Fin Dialogo·,·indices·:[]}]},·dialogueDataBaseFile·:[{·Dialogo·:·Noticias de última hora.·,·Efectos·:·Oscurecer=(true)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·'- Se ha descubierto que los exukentes pensaban en tomar la Estación Espacial Láctea por la fuerza...'·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·'- El tratado de paz galáctico fue un truco de los exukentes para robarnos y conquistarnos...'·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·'- Un ministro humano ha reunido a los representantes de los corgos y feriseos para firmar un pacto de expulsión...'·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·'- Los exukentes serán desterrados tomando todas las medidas necesarias...'·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·'- Estado de alarma, los trabajadores deberán volver a sus hogares por su seguridad...'·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Decides levantarte, abres la puerta de tu oficina y ves al resto de compañeros del CSE corriendo hacia sus viviendas...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Tú decides seguir la marea.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Eres de los últimos y todo el edificio está en silencio, quitando los pasos de todos los que huyen.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Antes de salir por la puerte, oyes un ruido en uno de los cuartos de baño cercanos a recepción.·,·Efectos·:·Dar Opciones=(Da igual, mi seguridad está antes @ irse | ¿Y si es un compañero en peligro? @ acudir)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Haces el esfuerzo de ingnorar lo que acaba de ocurrir y vuelves a tu hogar seguro. Libre de terroristas.·,·Efectos·:·Ir A Entrada=(fin)·,·Grupo·:·ENDING·,·Etiqueta·:·irse·},{·Dialogo·:··,·Efectos·:··,·Grupo·:··,·Etiqueta·:··},{·Dialogo·:·Sueltas el asa de la puerta y das media vuelta.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·acudir·},{·Dialogo·:·Si alguien está en los aseos puede que se haya herido y esté buscando un botiquín.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Cuanto más te acercas al aseo, más se escucha un leve sollozo.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Una tos y unas fosas nasales algo taponadas marcan el compás de la situación.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·En cuanto pisas el suelo de ajedrez de los aseos, el eco llega a la posible alma en apuros.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Tras eso, una recogida de mocos y un leve traqueteo insectoide cortan la situación y se crea un completo silencio.·,·Efectos·:·Dar Opciones=(Me voy, es una trampa @ irse | Preguntar quién es @ continua)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·continua·},{·Dialogo·:·No hay respuesta.·,·Efectos·:·Dar Opciones=(Adentrarse @ continua2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Una vez llegas al fondo, miras con cautela el último cubículo que estaba abierto.·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·continua2·},{·Dialogo·:·¡Por favor! ¡No me hagas daño! ¡Por favor <val[nick]>!·,·Efectos·:·Cambio Perfil=(Kripo neutro),Dar Opciones=(¿Kripo? @ c3)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Es todo una trampa...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·c3·},{·Dialogo·:·¡Nunca nos quisieron aquí!·,·Efectos·:·Cambio Perfil=(Kripo enfadado)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·HAN ESTADO TODO ESTE TIEMPO PINTÁNDONOS DE LADRONES Y ASESINOS·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Kripo vuelve a separar la mirada y sigue llorando·,·Efectos·:·Cambio Perfil=(), Dar Opciones=(Lo siento @ c4)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¿eh?·,·Efectos·:·Cambio Perfil=(Kripo neutro2), Dar Opciones=(Siento que no haya podido ayudarte @ c5)·,·Grupo·:·ENDING·,·Etiqueta·:·c4·},{·Dialogo·:·Es igual <val[nick]>, ya no hay nada que hacer, no puedo huir a ninguna parte.·,·Efectos·:·Cambio Perfil=(Kripo neutro), Dar Opciones=(¿Dónde está tu familia? @ c6)·,·Grupo·:·ENDING·,·Etiqueta·:·c5·},{·Dialogo·:·Probablemente sufriendo un golpe de estado si no los han matado ya los humanos...·,·Efectos·:·Dar Opciones=(¿Golpe de estado? @ c7)·,·Grupo·:·ENDING·,·Etiqueta·:·c6·},{·Dialogo·:·Sí... eh... lo he estado manteniendo en secreto...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·c7·},{·Dialogo·:·Mi nombre completo es Kripo Kosmi, es el apellido de la realeza exukente...·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Soy el príncipe exukente...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Vine a trabajar al CSE porque sabía que había un plan secreto para expulsar a los nuestros.·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·No pude obtener suficiente información...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·No fui lo suficientemente rápido...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Soy el príncipe más inútil que existe...·,·Efectos·:·Dar Opciones=(No te eches la culpa, nadie pudo... @ c8)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¡Sí pero se supone que soy el príncipe!·,·Efectos·:·Cambio Perfil=(Kripo enfadado)·,·Grupo·:·ENDING·,·Etiqueta·:·c8·},{·Dialogo·:·¡Mi casta se supone que es la mejor!·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¡Mi inteligencia debería de haber sido lo suficiente!·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Pero sólo he probado ser un inútil al que probablemente capturen o maten en cuanto la policía me vea.·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:·Dar Opciones=(Darle la mano @ ayudar)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¿?·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·ayudar·},{·Dialogo·:·¿Qué intentas?·,·Efectos·:·Cambio Perfil=(Kripo neutro2), Dar Opciones=(Ven conmigo @ c9)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·¿En tu coche? ¿A la bahía de transbordos más segura?...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·c9·},{·Dialogo·:·No sé...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·No me lo merezco, creo que ya he aceptado mi fin...·,·Efectos·:·Dar Opciones=(Príncipe o no, mereces vivir @ damn)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:·damn·},{·Dialogo·:·...·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Está bien...·,·Efectos·:·Cambio Perfil=(Kripo neutro)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Kripo extiende una de sus patas para agarrar la mano que le ofreciste.·,·Efectos·:·Cambio Perfil=()·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Se levanta...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·<val[nick]>... Gracias...·,·Efectos·:·Cambio Perfil=(Kripo neutro2)·,·Grupo·:·ENDING·,·Etiqueta·:··},{·Dialogo·:·Y así decidiste terminar esta aventura...·,·Efectos·:·Oscurecer=(false), Cambio Perfil=()·,·Grupo·:·ENDING·,·Etiqueta·:·fin·},{·Dialogo·:·...·,·Efectos·:··,·Grupo·:·ENDING·,·Etiqueta·:··}],·tableCodesNuevos·:··,·modVarGameplay·:··}");


-- --------------------------------------------------------

--
-- Estructura para la tabla `learningRecord`
--

CREATE TABLE `learningRecord` (
  `recordID` int NOT NULL,
  `actor` text NOT NULL COMMENT 'The player for whom the statement is made',
  `verb` text NOT NULL COMMENT 'the action that triggered the statement',
  `object` text NOT NULL COMMENT 'the object the player have manipulated/ is relevant to the action',
  `result` text COMMENT 'data produced after the action',
  `context` text COMMENT 'data related to the action',
  `timestamp` datetime DEFAULT NULL COMMENT 'the moment the statement was created (not when it was sent)',
  `whole_statement` text NOT NULL COMMENT 'the raw complete statement, for redundancy reasons'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `players`
--

CREATE TABLE `players` (
  `id` int NOT NULL,
  `email` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `nickname` varchar(50) NOT NULL,
  `password` varchar(50) NOT NULL,
  `fechaCreacion` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `savedfiles`
--

CREATE TABLE `savedfiles` (
  `id` int NOT NULL,
  `file` json DEFAULT NULL,
  `player_id` int NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `scores`
--

CREATE TABLE `scores` (
  `id` int NOT NULL,
  `player_id` int NOT NULL,
  `case_id` int DEFAULT NULL,
  `difficulty` int UNSIGNED NOT NULL,
  `score` int NOT NULL,
  `used_queries` int UNSIGNED NOT NULL,
  `time_spent` float NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- --------------------------------------------------------

--
-- Estructura para la tabla `tablesUnlockCode`
--

